begin;
create table if not exists public.health_goals(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,person_id uuid not null references public.persons(id) on delete cascade,goal_type text not null check(goal_type in ('hydration_ml')),target_value numeric not null check(target_value>0 and target_value<=20000),unit text not null check(unit in ('ml')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(person_id,goal_type));
create index if not exists health_goals_owner_idx on public.health_goals(user_id,person_id);alter table public.health_goals enable row level security;drop policy if exists health_goals_owner_all on public.health_goals;create policy health_goals_owner_all on public.health_goals for all using(auth.uid()=user_id) with check(auth.uid()=user_id and exists(select 1 from public.persons p where p.id=person_id and p.user_id=auth.uid()));commit;
